package main

import "strings"

// The GLOBAL map's header, from oracle/skill_stat_map_global_emit.py's HEADER. Extracted, not
// retyped: `{{` collapses, a literal `%` must be escaped for Sprintf, and backquotes stand in as @.
//
// Placeholders, in order: version, entries, mods, kept, omitted, omissions, dupnote
var ssgHeader = strings.ReplaceAll(ssgHeaderT, "@", "`")

const ssgHeaderT = `package raw

import (
	"github.com/Vilsol/go-pob/mod"
	"github.com/Vilsol/go-pob/utils"
)

// CODE GENERATED BY gopob's skill-stat-map-global emitter FROM PoB %s. DO NOT EDIT.
// Regenerate with @task data-regen -- --only skill-stat-map-global@ after a PoB pin bump.
//
// SkillStatMap is PoB's GLOBAL stat-to-modifier table (src/Data/SkillStatMap.lua, loaded at
// src/Modules/Data.lua:950). It is the FALLBACK: calcs.mergeSkillInstanceMods looks a stat up
// in the skill's own statMap first, and only a stat the skill declares nothing for falls
// through here via data.skillStatMapMeta.__index (src/Modules/Data.lua:951-963). go-pob ports
// the per-skill half separately as SkillStatMaps, and GetStatMapEntry (granted_effects.go)
// mirrors that order.
//
// PoB's DECLARATION ORDER and section comments are preserved. The upstream file is 1780 lines
// with no other navigation, and sorting the keys would make this file undiffable against the
// hand transcription it replaces.
//
// %s entries, %s mods, of which %d are emitted and %d are not
// representable and are omitted rather than mapped lossily:
%s
//
// The previous revision was 1818 hand-transcribed lines whose header read "Generated from PoB
// v2.18.1" with no emitter committed, so it could not be re-run against a new pin.
%s

func skill(dataKey string, dataValue float64) mod.Mod {
	// Stored by value, matching every other SkillData mod; consumers cast to
	// mod.SkillData (not *mod.SkillData).
	return mod.NewList("SkillData", mod.SkillData{
		Key:   dataKey,
		Value: dataValue,
	})
}

var SkillStatMap = map[string]*StatMap{
`
